CREATE TABLE run_model_identities (run_id TEXT NOT NULL REFERENCES runs(id), role TEXT NOT NULL CHECK(role IN ('confidence','reader','recovery')), model_requested TEXT NOT NULL, model_reported TEXT NOT NULL CHECK(length(model_reported) > 0), attempt_id TEXT NOT NULL REFERENCES vendor_calls(attempt_id), created_at TEXT NOT NULL, PRIMARY KEY (run_id, role, model_requested));
CREATE TRIGGER run_model_identities_no_update BEFORE UPDATE ON run_model_identities BEGIN SELECT RAISE(ABORT,'Run model identities are immutable'); END;
CREATE TRIGGER run_model_identities_no_delete BEFORE DELETE ON run_model_identities BEGIN SELECT RAISE(ABORT,'Run model identities are immutable'); END;
DROP VIEW daily_vendor_usage;
CREATE VIEW daily_vendor_usage AS WITH normalized AS (SELECT v.*, CASE WHEN json_valid(usage_json) THEN usage_json ELSE '{}' END AS safe_usage, CASE WHEN cost_nano IS NOT NULL AND length(cost_nano) BETWEEN 1 AND 16 AND cost_nano NOT GLOB '*[^0-9]*' AND (cost_nano='0' OR substr(cost_nano,1,1)!='0') AND CAST(cost_nano AS INTEGER) <= 9007199254740991 THEN CAST(cost_nano AS INTEGER) END AS nano_units FROM vendor_calls v) SELECT attempt_id,run_id,fingerprint,role,model_requested,created_at,nano_units, CASE WHEN nano_units IS NOT NULL AND json_type(safe_usage,'$.input_tokens')='integer' AND json_type(safe_usage,'$.output_tokens')='integer' AND json_extract(safe_usage,'$.input_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.output_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.input_tokens')+json_extract(safe_usage,'$.output_tokens') <= 9007199254740991 THEN json_extract(safe_usage,'$.input_tokens')+json_extract(safe_usage,'$.output_tokens') WHEN nano_units IS NOT NULL AND json_type(safe_usage,'$.input_tokens') IS NULL AND json_type(safe_usage,'$.output_tokens') IS NULL AND json_type(safe_usage,'$.prompt_tokens')='integer' AND json_type(safe_usage,'$.completion_tokens')='integer' AND json_extract(safe_usage,'$.prompt_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.completion_tokens') BETWEEN 0 AND 9007199254740991 AND json_extract(safe_usage,'$.prompt_tokens')+json_extract(safe_usage,'$.completion_tokens') <= 9007199254740991 THEN json_extract(safe_usage,'$.prompt_tokens')+json_extract(safe_usage,'$.completion_tokens') WHEN nano_units=0 AND usage_json IS NULL AND (status=429 OR status BETWEEN 500 AND 599) THEN 0 END AS token_units FROM normalized;
